package net.officefloor.hq.app.rollup;

import java.time.LocalDate;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/**
 * A change of the sheet's today first records one SNAPSHOT line per person, in list order, with their due-total as it
 * stood on the day being left, each also kept as one of the person's snapshot lines. Runs before the new today is
 * stored, ahead of any period closing and the rollup lines.
 */
public class RecordSnapshots {
    public void record(@Val SheetResponse sheet, @Val LocalDate today, @Val RollupBefore before, @Val ChangedBy by,
            SheetRepository sheets, PersonSnapshotRepository snapshots, Audit audit) {
        LocalDate leaving = sheets.today(sheet.id());
        if (today.equals(leaving)) {
            return;
        }
        for (Map.Entry<Long, Figures> e : before.snapshot().people().entrySet()) {
            Figures f = e.getValue();
            snapshots.insert(sheet.id(), e.getKey(), leaving, f.dueTotal());
            audit.record("SNAPSHOT sheet=" + sheet.id() + " by=" + by.name() + " name=" + f.name() + " due-total="
                    + (f.dueTotal() == null ? "n/a" : f.dueTotal().toPlainString()));
        }
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the sheet's figures before the change writes anything, so RecordRollup can tell what it moved. */
public class SnapshotRollup {
    public void snapshot(@Val SheetResponse sheet, Rollup rollup, Out<RollupBefore> before) {
        before.set(new RollupBefore(rollup.snapshot(sheet.id())));
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;

/** One of a person's snapshot lines: the day being left as the sheet's today moved on, and their due-total then
 *  (null: n/a). */
public record SnapshotLine(LocalDate day, BigDecimal dueTotal) {

    /** The line as shown: the day, then the due-total ("n/a" when none). */
    public String line() {
        return day + " " + (dueTotal == null ? "n/a" : dueTotal.toPlainString());
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The people's snapshot lines, one per SNAPSHOT written for them (read with the person, see PersonRepository). */
@Repository
public class PersonSnapshotRepository {

    private final JdbcTemplate jdbc;

    public PersonSnapshotRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Keep the person's due-total (null: n/a) as it stood on the day being left. */
    public void insert(String sheetId, long personId, LocalDate day, BigDecimal dueTotal) {
        jdbc.update("INSERT INTO person_snapshot (sheet_id, person_id, left_on, due_total) VALUES (?, ?, ?, ?)", sheetId,
                personId, Date.valueOf(day), dueTotal);
    }
}
-- A person's snapshot lines: one per SNAPSHOT written for them as the sheet's today moved on, with the day being left
-- and their due-total as it stood then (null: n/a). Listed oldest first (by id).
CREATE TABLE person_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    left_on   DATE           NOT NULL,
    due_total DECIMAL(19, 2)
);
CREATE INDEX person_snapshot_person ON person_snapshot (person_id, id);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.person_snapshot AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_snapshot t WHERE FALSE;
CREATE INDEX hist_person_snapshot_snapshot ON hist.person_snapshot (snapshot_id);
CREATE TABLE asof.person_snapshot AS SELECT * FROM person_snapshot WHERE FALSE;

